const uint16_t *ascii16_glyph(unsigned cp)
{
    if (cp < 0x20 || cp > 0x7E) return 0;
    return ascii16[cp - 0x20];
}

const uint16_t *cjk_glyph(unsigned cp)
{
    if (!cjk_glyphs_ready) cjk_glyphs_init();
    int lo = 0, hi = CJK_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cjk_cp[mid] == cp) return cjk_glyphs[mid];
        if (cjk_cp[mid] < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}

int cjk_halfwidth(unsigned cp)
{
    int lo = 0, hi = CJK_HALF_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cjk_half_cp[mid] == cp) return 1;
        if (cjk_half_cp[mid] < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
